    // ============ Structs ============

    /**
     * @notice Withdrawal request data structure.
     * @param shares The number of sUSDat shares escrowed.
     * @param usdatOwed The amount of USDat owed after processing.
     * @param timestamp The timestamp when the request was created.
     * @param minUsdatReceived The minimum USDat the user will accept (slippage protection).
     * @param status The current status of the request.
     */
    struct Request {
        uint256 shares;
        uint256 usdatOwed;
        uint256 timestamp;
        uint256 minUsdatReceived;
        RequestStatus status;
    }

    // ============ Errors ============

    /**
     * @dev Thrown when a zero amount is provided where a non-zero value is required.
     */
    error ZeroAmount();

    /**
     * @dev Thrown when attempting to process a request that has already been processed.
     */
    error AlreadyProcessed();

    /**
     * @dev Thrown when there are no claimable requests for the user.
     */
    error NothingToClaim();

    /**
     * @dev Thrown when the caller is not the owner of the token.
     */
    error NotOwner();

    /**
     * @dev Thrown when an operation requires a blacklisted address but the address is not blacklisted.
     */
    error NotBlacklisted();

    /**
     * @dev Thrown when invalid inputs are provided.
     */
    error InvalidInputs();

    /**
     * @dev Thrown when the execution price doesn't match expected within tolerance.
     */
    error ExecutionPriceMismatch();

    /**
     * @dev Thrown when the execution price doesn't match the oracle price within tolerance.
     */
    error OraclePriceMismatch();

    /**
     * @dev Thrown when attempting to claim a request that hasn't been processed yet.
     */
    error RequestNotProcessed();

    /**
     * @dev Thrown when an operation involves a blacklisted address.
     */
    error AddressBlacklisted();

    /**
     * @dev Thrown when slippage protection is triggered (received less than minimum).
     */
    error SlippageExceeded();

    /**
     * @dev Thrown when attempting to sell more STRC than the vested balance.
     */
    error ExceedsVestedBalance();

    /**
     * @dev Thrown when attempting to process a request that is not locked.
     */
    error RequestNotLocked();

    // ============ Events ============

    /**
     * @dev Emitted when a new withdrawal request is created.
     * @param tokenId The NFT token ID representing the request.
     * @param user The user who created the request.
     * @param shares The number of shares escrowed.
     * @param timestamp The timestamp of the request.
     */
    event WithdrawalRequested(uint256 indexed tokenId, address indexed user, uint256 shares, uint256 timestamp);

    /**
     * @dev Emitted when requests are locked for processing.
     * @param tokenIds The array of token IDs that were locked.
     */
    event RequestsLocked(uint256[] tokenIds);

    /**
     * @dev Emitted when requests are unlocked after a failed processing attempt.
     * @param tokenIds The array of token IDs that were unlocked.
     */
    event RequestsUnlocked(uint256[] tokenIds);

    /**
     * @dev Emitted when a withdrawal request is processed.
     * @param tokenId The NFT token ID of the processed request.
     * @param shares The number of shares that were redeemed.
     * @param usdatAmount The amount of USDat allocated to the user.
     */
    event WithdrawalProcessed(uint256 indexed tokenId, uint256 shares, uint256 usdatAmount);

    /**
     * @dev Emitted when a user claims their USDat.
     * @param tokenId The NFT token ID that was claimed.
     * @param user The user who claimed.
     * @param usdatAmount The amount of USDat claimed.
     */
    event Claimed(uint256 indexed tokenId, address indexed user, uint256 usdatAmount);

    /**
     * @dev Emitted when processed funds are seized from a blacklisted user.
     * @param tokenId The NFT token ID of the seized request.
     * @param user The blacklisted user whose funds were seized.
     * @param usdatAmount The amount of USDat seized.
     * @param to The address that received the seized funds.
     */
    event FundsSeized(uint256 indexed tokenId, address indexed user, uint256 usdatAmount, address indexed to);

    /**
     * @dev Emitted when a pending request is seized from a blacklisted user.
     * @param tokenId The NFT token ID of the seized request.
     * @param user The blacklisted user whose request was seized.
     * @param to The address that received the NFT.
     */
    event RequestSeized(uint256 indexed tokenId, address indexed user, address indexed to);

    /**
     * @dev Emitted when a user updates their minimum USDat amount.
     * @param tokenId The NFT token ID of the updated request.
     * @param newMinUsdatReceived The new minimum USDat amount.
     */
    event MinUsdatReceivedUpdated(uint256 indexed tokenId, uint256 newMinUsdatReceived);

    // ============ Admin Functions ============

    /**
     * @notice Pauses the contract.
     * @dev Only callable by addresses with the COMPLIANCE_ROLE.
     */
    function pause() external;

    /**
     * @notice Unpauses the contract.
     * @dev Only callable by addresses with the DEFAULT_ADMIN_ROLE.
     */
    function unpause() external;

    // ============ Request Creation ============

    /**
     * @notice Creates a new withdrawal request.
     * @dev Called by StakedUSDat when a user requests redemption.
     * Mints an NFT to the user representing their withdrawal request.
     * Only callable by addresses with the STAKED_USDAT_ROLE.
     * @param user The user requesting withdrawal.
     * @param shares The amount of sUSDat shares escrowed.
     * @param minUsdatReceived The minimum amount of USDat the user will accept.
     * @return tokenId The NFT token ID (same as request ID).
     */
    function addRequest(address user, uint256 shares, uint256 minUsdatReceived) external returns (uint256 tokenId);

    /**
     * @notice Updates the minimum USDat amount for a pending withdrawal request.
     * @dev Can only be called by the NFT owner. For InProgress requests, can only lower
     * the minimum (more lenient slippage). For Requested status, can adjust in any direction.
     * @param tokenId The token ID of the request to update.
     * @param newMinUsdatReceived The new minimum USDat amount.
     */
    function updateMinUsdatReceived(uint256 tokenId, uint256 newMinUsdatReceived) external;

    // ============ Processing Functions ============

    /**
     * @notice Locks requests for processing.
     * @dev Prevents user modifications while requests are being processed off-chain.
     * Only callable by addresses with the PROCESSOR_ROLE.
     * @param tokenIds Array of token IDs to lock.
     */
    function lockRequests(uint256[] calldata tokenIds) external;

    /**
     * @notice Unlocks requests if processing fails.
     * @dev Returns requests to the Requested state so users can modify them.
     * Only callable by addresses with the PROCESSOR_ROLE.
     * @param tokenIds Array of token IDs to unlock.
     */
    function unlockRequests(uint256[] calldata tokenIds) external;

    /**
     * @notice Processes a batch of withdrawal requests.
     * @dev Validates the execution against oracle prices and allocates USDat pro-rata.
     * Burns the escrowed shares and decreases strcBalance, then transfers USDat for users to claim.
     * Only callable by addresses with the PROCESSOR_ROLE.
     * @param tokenIds Array of token IDs to process.
     * @param totalUsdatReceived Amount of USDat received from selling STRC off-chain.
     * @param totalStrcSold Amount of STRC that was sold off-chain.
     * @param executionPrice The price per STRC in USDat terms (8 decimals) for validation.
     */
    function processRequests(
        uint256[] calldata tokenIds,
        uint256 totalUsdatReceived,
        uint256 totalStrcSold,
        uint256 executionPrice
    ) external;

    // ============ Claiming Functions ============

    /**
     * @notice Claims a specific withdrawal request by token ID.
     * @dev Burns the NFT and transfers USDat to the caller.
     * @param tokenId The NFT token ID to claim.
     * @return amount The amount of USDat claimed.
     */
    function claim(uint256 tokenId) external returns (uint256 amount);

    /**
     * @notice Claims multiple withdrawal requests.
     * @dev Burns the NFTs and transfers total USDat to the caller.
     * @param tokenIds Array of token IDs to claim.
     * @return totalAmount The total amount of USDat claimed.
     */
    function claimBatch(uint256[] calldata tokenIds) external returns (uint256 totalAmount);

    /**
     * @notice Claims specific withdrawal requests for a user.
     * @dev Called by StakedUSDat on behalf of the user.
     * Only callable by addresses with the STAKED_USDAT_ROLE.
     * @param user The user who owns the NFTs and will receive the USDat.
     * @param tokenIds Array of token IDs to claim.
     * @return totalAmount The total amount of USDat claimed.
     */
    function claimBatchFor(address user, uint256[] calldata tokenIds) external returns (uint256 totalAmount);

    /**
     * @notice Claims all processed withdrawals for the caller.
     * @dev Iterates through all NFTs owned by caller. Gas cost scales with ownership count.
     * @return totalAmount The total amount of USDat claimed.
     */
    function claimAll() external returns (uint256 totalAmount);

    /**
     * @notice Claims all processed withdrawals for a user.
     * @dev Called by StakedUSDat on behalf of the user.
     * Only callable by addresses with the STAKED_USDAT_ROLE.
     * @param user The user to claim for.
     * @return totalAmount The total amount of USDat claimed.
     */
    function claimAllFor(address user) external returns (uint256 totalAmount);

    // ============ View Functions ============

    /**
     * @notice Gets all token IDs owned by the caller.
     * @return tokenIds Array of token IDs owned by the caller.
     */
    function getMyRequests() external view returns (uint256[] memory tokenIds);

    /**
     * @notice Gets all token IDs owned by a user.
     * @param user The user to query.
     * @return tokenIds Array of token IDs owned by the user.
     */
    function getUserRequests(address user) external view returns (uint256[] memory tokenIds);

    /**
     * @notice Gets claimable amount and token IDs for a user.
     * @param user The user to query.
     * @return total The total claimable USDat amount.
     * @return claimableIds Array of claimable token IDs.
     */
    function getClaimable(address user) external view returns (uint256 total, uint256[] memory claimableIds);

    /**
     * @notice Gets pending (unprocessed) requests for a user.
     * @param user The user to query.
     * @return totalShares The total shares in pending requests.
     * @return pendingIds Array of pending token IDs.
     */
    function getPending(address user) external view returns (uint256 totalShares, uint256[] memory pendingIds);

    /**
     * @notice Gets a specific request's details.
     * @param tokenId The token ID to query.
     * @return The request data.
     */
    function getRequest(uint256 tokenId) external view returns (Request memory);

    /**
     * @notice Gets the status of a specific request.
     * @param tokenId The token ID to check.
     * @return The current status of the request.
     */
    function getStatus(uint256 tokenId) external view returns (RequestStatus);

    /**
     * @notice Checks if a specific request is claimable.
     * @dev Returns false if token doesn't exist (was already claimed/burned).
     * @param tokenId The token ID to check.
     * @return True if the request is claimable.
     */
    function isClaimable(uint256 tokenId) external view returns (bool);

    /**
     * @notice Gets the number of pending requests in the queue.
     * @return The pending request count.
     */
    function getPendingCount() external view returns (uint256);

    /**
     * @notice Gets total sUSDat shares waiting to be processed.
     * @return The total pending shares.
     */
    function getTotalPendingShares() external view returns (uint256);

    /**
     * @notice Gets the total number of requests ever made.
     * @return The total request count.
     */
    function getTotalRequests() external view returns (uint256);

    /**
     * @notice Gets pending request IDs within a range.
     * @param start Starting tokenId (inclusive).
     * @param end Ending tokenId (exclusive).
     * @return pendingIds Array of pending tokenIds in the range.
     */
    function getPendingIdsInRange(uint256 start, uint256 end) external view returns (uint256[] memory pendingIds);

    // ============ Compliance Functions ============

    /**
     * @notice Seizes pending requests from blacklisted holders.
     * @dev Transfers NFTs from blacklisted users to the specified address.
     * Only works for Requested and InProgress status.
     * Only callable by addresses with the COMPLIANCE_ROLE.
     * @param tokenIds Array of token IDs to seize.
     * @param to The address to transfer the NFTs to.
     */
    function seizeRequests(uint256[] calldata tokenIds, address to) external;

    /**
     * @notice Seizes processed requests from blacklisted holders.
     * @dev Burns NFTs and transfers USDat to the specified address.
     * Only works for Processed status.
     * Only callable by addresses with the COMPLIANCE_ROLE.
     * @param tokenIds Array of token IDs to seize.
     * @param to The address to transfer the USDat to.
     */
    function seizeBlacklistedFunds(uint256[] calldata tokenIds, address to) external;
}
"
    },
    "src/interfaces/IStrcPriceOracle.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title IStrcPriceOracle
 * @notice Interface for the STRC price oracle contract
 * @dev Provides validated STRC price data with staleness and bounds checking.
 * This contract wraps a Chainlink-compatible oracle and adds additional validation.
 */
interface IStrcPriceOracle {
    /**
     * @dev Thrown when the oracle returns an invalid, stale, or out-of-bounds price.
     */
    error InvalidOraclePrice();

    /**
     * @dev Thrown when a zero address is provided where a valid address is required.
     */
    error InvalidZeroAddress();

    /**
     * @dev Thrown when the staleness value exceeds MAX_STALENESS.
     */
    error InvalidStaleness();

    /**
     * @dev Thrown when invalid price bounds are provided (minPrice must be > 0 and < maxPrice).
     */
    error InvalidPriceBounds();

    /**
     * @dev Emitted when the maximum price staleness setting is updated.
     * @param newStaleness The new staleness value in seconds.
     */
    event MaxPriceStalenessUpdated(uint256 newStaleness);

    /**
     * @dev Emitted when the acceptable price bounds are updated.
     * @param newMinPrice The new minimum acceptable price.
     * @param newMaxPrice The new maximum acceptable price.
     */
    event PriceBoundsUpdated(uint256 newMinPrice, uint256 newMaxPrice);

    /**
     * @dev Emitted when the oracle address is updated.
     * @param oldOracle The previous oracle address.
     * @param newOracle The new oracle address.
     */
    event OracleUpdated(address indexed oldOracle, address indexed newOracle);

    /**
     * @notice Updates the price oracle address.
     * @dev Only callable by addresses with the DEFAULT_ADMIN_ROLE.
     * @param newOracle The new oracle address. Cannot be the zero address.
     */
    function updateOracle(address newOracle) external;

    /**
     * @notice Updates the maximum allowed price staleness.
     * @dev Only callable by addresses with the DEFAULT_ADMIN_ROLE.
     * The new staleness value must not exceed MAX_STALENESS.
     * @param newStaleness The new staleness value in seconds.
     */
    function setMaxPriceStaleness(uint256 newStaleness) external;

    /**
     * @notice Updates the acceptable price bounds for oracle validation.
     * @dev Only callable by addresses with the DEFAULT_ADMIN_ROLE.
     * The minPrice must be greater than 0 and less than maxPrice.
     * @param newMinPrice The new minimum acceptable price.
     * @param newMaxPrice The new maximum acceptable price.
     */
    function setPriceBounds(uint256 newMinPrice, uint256 newMaxPrice) external;

    /**
     * @notice Returns the current oracle address.
     * @return The address of the price oracle contract.
     */
    function getOracle() external view returns (address);

    /**
     * @notice Fetches the latest STRC price from the oracle.
     * @dev Uses latestRoundData for staleness checks (Chainlink recommended).
     * Reverts if the oracle address is zero, the price is stale, negative, or out of bounds.
     * @return price The latest price from the oracle (scaled by oracle decimals).
     * @return oracleDecimals The number of decimals in the price.
     */
    function getPrice() external view returns (uint256 price, uint8 oracleDecimals);

    /**
     * @notice Returns the maximum allowed staleness setting.
     * @return The maximum staleness constant (6 hours).
     */
    function MAX_STALENESS() external view returns (uint256);

    /**
     * @notice Returns the current maximum price staleness setting.
     * @return The maximum allowed staleness in seconds.
     */
    function maxPriceStaleness() external view returns (uint256);

    /**
     * @notice Returns the minimum acceptable price from the oracle.
     * @return The minimum price (default $20 with 8 decimals).
     */
    function minPrice() external view returns (uint256);

    /**
     * @notice Returns the maximum acceptable price from the oracle.
     * @return The maximum price (default $150 with 8 decimals).
     */
    function maxPrice() external view returns (uint256);
}
"
    },
    "src/interfaces/IStakedUSDat.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";

/**
 * @title IStakedUSDat
 * @author Saturn
 * @notice Interface for the StakedUSDat (sUSDat) ERC4626 vault contract.
 * @dev StakedUSDat is a UUPS upgradeable ERC4626 vault for staking USDat.
 * Users deposit USDat and receive sUSDat shares representing their stake.
 * The vault holds both USDat and tracks STRC holdings internally via strcBalance.
 * STRC holdings are managed by the Saturn entity. Rewards are distributed as STRC
 * and vest linearly over a configurable period to prevent front-running attacks.
 */
interface IStakedUSDat is IERC4626 {
    // ============ Errors ============

    /**
     * @dev Thrown when a zero address is provided where a valid address is required.
     */
    error InvalidZeroAddress();

    /**
     * @dev Thrown when an operation involves a zero amount where a non-zero value is required.
     */
    error ZeroAmount();

    /**
     * @dev Thrown when an operation is not allowed (e.g., direct withdraw/redeem).
     */
    error OperationNotAllowed();

    /**
     * @dev Thrown when attempting to un-blacklist an address that is not blacklisted.
     */
    error AddressNotBlacklisted();

    /**
     * @dev Thrown when an operation involves a blacklisted address.
     */
    error AddressBlacklisted();

    /**
     * @dev Thrown when attempting to redistribute locked amounts with no valid recipients.
     */
    error NoRecipientsForRedistribution();

    /**
     * @dev Thrown when attempting to blacklist an admin address.
     */
    error CannotBlacklistAdmin();

    /**
     * @dev Thrown when an operation requires more balance than available.
     */
    error InsufficientBalance();

    /**
     * @dev Thrown when attempting to change vesting period or add rewards while rewards are still vesting.
     */
    error StillVesting();

    /**
     * @dev Thrown when an invalid vesting period is provided.
     */
    error InvalidVestingPeriod();

    /**
     * @dev Thrown when a withdrawal amount is below the minimum threshold.
     */
    error WithdrawalTooSmall();

    /**
     * @dev Thrown when slippage protection is triggered (received less than minimum).
     */
    error SlippageExceeded();

    /**
     * @dev Thrown when the execution price doesn't match expected within tolerance.
     */
    error ExecutionPriceMismatch();

    /**
     * @dev Thrown when the execution price doesn't match the oracle price within tolerance.
     */
    error OraclePriceMismatch();

    /**
     * @dev Thrown when an invalid fee value is provided.
     */
    error InvalidFee();

    /**
     * @dev Thrown when rewards exceed the maximum allowed percentage of totalAssets.
     */
    error RewardsExceedMax();

    // ============ Events ============

    /**
     * @dev Emitted when an address is added to the blacklist.
     * @param target The address that was blacklisted.
     */
    event Blacklisted(address indexed target);

    /**
     * @dev Emitted when an address is removed from the blacklist.
     * @param target The address that was un-blacklisted.
     */
    event UnBlacklisted(address indexed target);

    /**
     * @dev Emitted when USDat is converted to/from tSTRC.
     * @param usdatAmount The amount of USDat involved in the conversion.
     * @param strcAmount The amount of tSTRC involved in the conversion.
     */
    event Converted(uint256 usdatAmount, uint256 strcAmount);

    /**
     * @dev Emitted when rewards are transferred into the contract.
     * @param amount The amount of tSTRC rewards received.
     * @param newVestingAmount The total amount now vesting.
     */
    event RewardsReceived(uint256 amount, uint256 newVestingAmount);

    /**
     * @dev Emitted when locked amounts are redistributed from a blacklisted address.
     * @param from The blacklisted address whose funds were redistributed.
     * @param amount The amount of shares that were burned.
     */
    event LockedAmountRedistributed(address indexed from, uint256 amount);

    /**
     * @dev Emitted when the vesting period is updated.
     * @param oldPeriod The previous vesting period in seconds.
     * @param newPeriod The new vesting period in seconds.
     */
    event VestingPeriodUpdated(uint256 oldPeriod, uint256 newPeriod);

    /**
     * @dev Emitted when the deposit fee is updated.
     * @param newFee The new deposit fee in basis points.
     */
    event DepositFeeUpdated(uint256 newFee);

    /**
     * @dev Emitted when the fee recipient is updated.
     * @param newRecipient The new fee recipient address.
     */
    event FeeRecipientUpdated(address indexed newRecipient);

    /**
     * @dev Emitted when the price tolerance is updated.
     * @param newToleranceBps The new tolerance in basis points.
     */
    event ToleranceUpdated(uint256 newToleranceBps);

    /**
     * @dev Emitted when the max rewards basis points is updated.
     * @param newMaxBps The new max rewards in basis points.
     */
    event MaxRewardsBpsUpdated(uint256 newMaxBps);

    // ============ Blacklist Functions ============

    /**
     * @notice Adds an address to the blacklist.
     * @dev Only callable by addresses with the COMPLIANCE_ROLE.
     * Cannot blacklist addresses with DEFAULT_ADMIN_ROLE.
     * @param target The address to blacklist.
     */
    function addToBlacklist(address target) external;

    /**
     * @notice Removes an address from the blacklist.
     * @dev Only callable by addresses with the COMPLIANCE_ROLE.
     * @param target The address to un-blacklist.
     */
    function removeFromBlacklist(address target) external;

    /**
     * @notice Checks if an address is blacklisted.
     * @param account The address to check.
     * @return True if the address is blacklisted, false otherwise.
     */
    function isBlacklisted(address account) external view returns (bool);

    /**
     * @notice Burns shares from a blacklisted address, redistributing value to other holders.
     * @dev Only callable by addresses with the DEFAULT_ADMIN_ROLE.
     * The target address must be blacklisted and have a positive balance.
     * @param from The blacklisted address to redistribute from.
     */
    function redistributeLockedAmount(address from) external;

    // ============ Asset Management Functions ============

    /**
     * @notice Rescues tokens accidentally sent to the contract.
     * @dev Only callable by addresses with the DEFAULT_ADMIN_ROLE.
     * For USDat, only allows rescuing amounts above the internally tracked balance.
     * @param token The address of the token to rescue.
     * @param amount The amount of tokens to rescue.
     * @param to The address to send the rescued tokens to.
     */
    function rescueTokens(address token, uint256 amount, address to) external;

    /**
     * @notice Converts USDat to STRC when the entity purchases STRC from the market.
     * @dev Only callable by addresses with the PROCESSOR_ROLE.
     * Decreases usdatBalance and increases strcBalance based on the purchase price.
     * @param usdatAmount The amount of USDat to convert.
     * @param strcAmount The amount of STRC to add.
     * @param strcPurchasePrice The price per STRC in USDat terms (8 decimals).
     */
    function convertFromUsdat(uint256 usdatAmount, uint256 strcAmount, uint256 strcPurchasePrice) external;

    /**
     * @notice Converts STRC to USDat when the entity sells STRC to the market.
     * @dev Only callable by addresses with the PROCESSOR_ROLE.
     * Decreases strcBalance and increases usdatBalance based on the sale price.
     * Can only convert vested STRC (unvested rewards are protected).
     * @param strcAmount The amount of STRC to remove.
     * @param usdatAmount The amount of USDat to add.
     * @param strcSalePrice The price per STRC in USDat terms (8 decimals).
     */
    function convertFromStrc(uint256 strcAmount, uint256 usdatAmount, uint256 strcSalePrice) external;

    /**
     * @notice Transfers STRC rewards into the contract with linear vesting.
     * @dev Only callable by addresses with the PROCESSOR_ROLE.
     * Cannot be called while previous rewards are still vesting.
     * Rewards vest linearly over the vestingPeriod to prevent front-running.
     * @param amount The amount of STRC to add as rewards.
     */
    function transferInRewards(uint256 amount) external;

    // ============ Deposit Functions ============

    /**
     * @notice Deposits assets with slippage protection.
     * @dev Reverts if the shares received would be less than minShares.
     * @param assets The amount of assets to deposit.
     * @param receiver The address to receive the shares.
     * @param minShares The minimum number of shares to receive.
     * @return shares The number of shares minted.
     */
    function depositWithMinShares(uint256 assets, address receiver, uint256 minShares) external returns (uint256 shares);

    /**
     * @notice Mints shares with slippage protection.
     * @dev Reverts if the assets required would exceed maxAssets.
     * @param shares The number of shares to mint.
     * @param receiver The address to receive the shares.
     * @param maxAssets The maximum amount of assets to spend.
     * @return assets The amount of assets spent.
     */
    function mintWithMaxAssets(uint256 shares, address receiver, uint256 maxAssets) external returns (uint256 assets);

    /**
     * @notice Deposits assets with EIP-2612 permit for gasless approval.
     * @dev Combines permit and deposit in a single transaction.
     * @param assets The amount of assets to deposit.
     * @param receiver The address to receive the shares.
     * @param minShares The minimum number of shares to receive (slippage protection).
     * @param deadline The permit signature deadline.
     * @param v The permit signature v component.
     * @param r The permit signature r component.
     * @param s The permit signature s component.
     * @return shares The number of shares minted.
     */
    function depositWithPermit(
        uint256 assets,
        address receiver,
        uint256 minShares,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external returns (uint256 shares);

    /**
     * @notice Mints shares with EIP-2612 permit for gasless approval.
     * @dev Combines permit and mint in a single transaction.
     * @param shares The number of shares to mint.
     * @param receiver The address to receive the shares.
     * @param maxAssets The maximum amount of assets to spend (slippage protection).
     * @param deadline The permit signature deadline.
     * @param v The permit signature v component.
     * @param r The permit signature r component.
     * @param s The permit signature s component.
     * @return assets The amount of assets spent.
     */
    function mintWithPermit(
        uint256 shares,
        address receiver,
        uint256 maxAssets,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external returns (uint256 assets);

    /**
     * @notice Deposits assets with EIP-1271 permit for smart contract wallet approval.
     * @dev Combines permit and deposit in a single transaction. Supports smart contract
     * wallets like Gnosis Safe, Argent, etc. that implement EIP-1271.
     * @param assets The amount of assets to deposit.
     * @param receiver The address to receive the shares.
     * @param minShares The minimum number of shares to receive (slippage protection).
     * @param deadline The permit signature deadline.
     * @param signature The EIP-1271 compatible signature bytes.
     * @return shares The number of shares minted.
     */
    function depositWithPermit(
        uint256 assets,
        address receiver,
        uint256 minShares,
        uint256 deadline,
        bytes memory signature
    ) external returns (uint256 shares);

    /**
     * @notice Mints shares with EIP-1271 permit for smart contract wallet approval.
     * @dev Combines permit and mint in a single transaction. Supports smart contract
     * wallets like Gnosis Safe, Argent, etc. that implement EIP-1271.
     * @param shares The number of shares to mint.
     * @param receiver The address to receive the shares.
     * @param maxAssets The maximum amount of assets to spend (slippage protection).
     * @param deadline The permit signature deadline.
     * @param signature The EIP-1271 compatible signature bytes.
     * @return assets The amount of assets spent.
     */
    function mintWithPermit(
        uint256 shares,
        address receiver,
        uint256 maxAssets,
        uint256 deadline,
        bytes memory signature
    ) external returns (uint256 assets);

    // ============ Withdrawal Functions ============

    /**
     * @notice Requests a redemption by escrowing shares in the withdrawal queue.
     * @dev Standard ERC4626 withdraw/redeem are disabled. Use this function instead.
     * Transfers shares to the withdrawal queue and mints an NFT representing the request.
     * @param shares The number of shares to redeem.
     * @param minUsdatReceived The minimum amount of USDat the user will accept.
     * @return requestId The ID of the withdrawal request NFT.
